/** static void MovePyramidBagItemSlotInList(u8 from, u8 to) */
export function MovePyramidBagItemSlotInList(from: any, to: any): any {
  let itemIds: any = gSaveBlock2Ptr.frontier.pyramidBag.itemId[gSaveBlock2Ptr.frontier.lvlMode];
      let quantities: any = gSaveBlock2Ptr.frontier.pyramidBag.quantity[gSaveBlock2Ptr.frontier.lvlMode];

      if (from != to)
      {
          let i: any = null;
          let firstSlotItemId: any = itemIds[from];
          let firstSlotQuantity: any = quantities[from];

          if (to > from)
          {
              to--;
              for (i = from; i < to; i++)
              {
                  itemIds[i] = itemIds[i + 1];
                  quantities[i] = quantities[i + 1];
              }
          }
          else
          {
              for (i = from; i > to; i--)
              {
                  itemIds[i] = itemIds[i - 1];
                  quantities[i] = quantities[i - 1];
              }
          }
          itemIds[to] = firstSlotItemId;
          quantities[to] = firstSlotQuantity;
      }
}

/** static void CompactItems(void) */
export function CompactItems(): any {
  let i, j;
      let itemIds: any = gSaveBlock2Ptr.frontier.pyramidBag.itemId[gSaveBlock2Ptr.frontier.lvlMode];
      let quantities: any = gSaveBlock2Ptr.frontier.pyramidBag.quantity[gSaveBlock2Ptr.frontier.lvlMode];

      for (i = 0; i < PYRAMID_BAG_ITEMS_COUNT; i++)
      {
          if (itemIds[i] == ITEM_NONE || quantities[i] == 0)
          {
              itemIds[i] = ITEM_NONE;
              quantities[i] = 0;
          }
      }
      for (i = 0; i < PYRAMID_BAG_ITEMS_COUNT - 1; i++)
      {
          for (j = i + 1; j < PYRAMID_BAG_ITEMS_COUNT; j++)
          {
              if (itemIds[i] == ITEM_NONE || quantities[i] == 0)
                  SwapItems(i, j);
          }
      }
}

