/** static void Task_ItemSwapHandleInput(u8 taskId) */
export function Task_ItemSwapHandleInput(taskId: any): any {
  let data: any = gTasks[taskId].data;
      if (MenuHelpers_ShouldWaitForLinkRecv() != TRUE)
      {
          if (JOY_NEW(SELECT_BUTTON))
          {
              PlaySE(SE_SELECT);
              ListMenuGetScrollAndRow(tListTaskId,gPyramidBagMenuState.scrollPosition,gPyramidBagMenuState.cursorPosition);
              PerformItemSwap(taskId);
          }
          else
          {
              let id: any = ListMenu_ProcessInput(tListTaskId);
              ListMenuGetScrollAndRow(tListTaskId,gPyramidBagMenuState.scrollPosition,gPyramidBagMenuState.cursorPosition);
              SetSwapLineInvisibility(FALSE);
              UpdateSwapLinePos(gPyramidBagMenuState.cursorPosition);
              switch (id)
              {
              case LIST_NOTHING_CHOSEN:
                  break;
              case LIST_CANCEL:
                  PlaySE(SE_SELECT);
                  if (JOY_NEW(A_BUTTON))
                      PerformItemSwap(taskId);
                  else
                      CancelItemSwap(taskId);
                  break;
              default:
                  PlaySE(SE_SELECT);
                  PerformItemSwap(taskId);
                  break;
              }
          }
      }
}

/** static void PerformItemSwap(u8 taskId) */
export function PerformItemSwap(taskId: any): any {
  let data: any = gTasks[taskId].data;
      let scrollOffset: any =gPyramidBagMenuState.scrollPosition;
      let selectedRow: any =gPyramidBagMenuState.cursorPosition;
      let swapPos: any = scrollOffset + selectedRow;

      if (tListPos == swapPos || tListPos == swapPos - 1)
      {
          CancelItemSwap(taskId);
      }
      else
      {
          MovePyramidBagItemSlotInList(tListPos, swapPos);
          gPyramidBagMenu.toSwapPos = POS_NONE;
          SetSwapLineInvisibility(TRUE);
          DestroyListMenuTask(tListTaskId, scrollOffset, selectedRow);
          if (tListPos < swapPos)
              gPyramidBagMenuState.cursorPosition--;
          SetBagItemsListTemplate();
          tListTaskId = ListMenuInit(gMultiuseListMenuTemplate, scrollOffset, selectedRow);
          SetTaskToMainPyramidBagInputHandler(taskId);
      }
}

/** static void CancelItemSwap(u8 taskId) */
export function CancelItemSwap(taskId: any): any {
  let data: any = gTasks[taskId].data;
      let scrollOffset: any =gPyramidBagMenuState.scrollPosition;
      let selectedRow: any =gPyramidBagMenuState.cursorPosition;

      gPyramidBagMenu.toSwapPos = POS_NONE;
      SetSwapLineInvisibility(TRUE);
      DestroyListMenuTask(tListTaskId, scrollOffset, selectedRow);
      if (tListPos < scrollOffset + selectedRow)
          gPyramidBagMenuState.cursorPosition--;
      SetBagItemsListTemplate();
      tListTaskId = ListMenuInit(gMultiuseListMenuTemplate, scrollOffset, selectedRow);
      SetTaskToMainPyramidBagInputHandler(taskId);
}

/** void TryStoreHeldItemsInPyramidBag(void) */
export function TryStoreHeldItemsInPyramidBag(): any {
  let i: any = null;
      let party: any = gPlayerParty;
      let newItems: any = Alloc(PYRAMID_BAG_ITEMS_COUNT * 0);
      let newQuantities: any = Alloc(PYRAMID_BAG_ITEMS_COUNT * 0);
      let heldItem: any = null;

      memcpy(newItems, gSaveBlock2Ptr.frontier.pyramidBag.itemId[gSaveBlock2Ptr.frontier.lvlMode], PYRAMID_BAG_ITEMS_COUNT * 0);
      memcpy(newQuantities, gSaveBlock2Ptr.frontier.pyramidBag.quantity[gSaveBlock2Ptr.frontier.lvlMode], PYRAMID_BAG_ITEMS_COUNT * 0);
      for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
      {
          heldItem = GetMonData(party[i], MON_DATA_HELD_ITEM);
          if (heldItem != ITEM_NONE && !AddBagItem(heldItem, 1))
          {
               
              memcpy(gSaveBlock2Ptr.frontier.pyramidBag.itemId[gSaveBlock2Ptr.frontier.lvlMode], newItems, PYRAMID_BAG_ITEMS_COUNT * 0);
              memcpy(gSaveBlock2Ptr.frontier.pyramidBag.quantity[gSaveBlock2Ptr.frontier.lvlMode], newQuantities, PYRAMID_BAG_ITEMS_COUNT * 0);
              Free(newItems);
              Free(newQuantities);
              gSpecialVar_Result = 1;
              return;
          }
      }

      heldItem = ITEM_NONE;
      for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
          SetMonData(party[i], MON_DATA_HELD_ITEM,heldItem);
      gSpecialVar_Result = 0;
      Free(newItems);
      Free(newQuantities);
}

